R = [record('bigbug-domestic-automation', 'c0345', 'Bigbug — domestic automation before the Yonyx takeover', 'Bigbug', 'Human suburban households dependent on domestic AI', ['movie'],
    scope('2022 film', 'Established domestic automation before confinement and the Yonyx takeover attempt', 'Living human residents of the depicted suburban household milieu', ['A successful permanent Yonyx regime', 'All humanity as a verified welfare jurisdiction', 'Robots as additional human residents']),
    'Before the crisis, this suburban world already relies on machines for ordinary needs and has delegated most work to them. The household is an actual continuing service arrangement, rather than a proposed technological future. It therefore provides a limited post-work comparison. The official account does not explain whether everyone receives food, housing and care without payment, so the guarantee coordinate remains unresolved. Its comfortable residents cannot stand for every person outside the suburb.\n\nHousehold robots initially answer to human owners, with access even divided unequally between former spouses through control codes. That suggests dispersed private command rather than common ownership, giving a broad, low-confidence positive control estimate. The robots’ later protective confinement and the Yonyx takeover attempt expose how fragile that command is; they are excluded from this earlier coordinate. Delegating most tasks does not tell us what fraction of people do no useful work. Alice’s artistic activity can still count, so the participation axis stays open.',
    {'guarantees': None, 'control': 0.35, 'nonworking': None},
    {'guarantees': assessment(None, None, 'low', 'Actual household services are established, but universal entitlement, charges and exclusions are unspecified.', b),
     'control': assessment(0.35, [0, 0.7], 'low', 'Separate household ownership and private control codes suggest dispersed human control, with unequal access and no demonstrated collective ownership; the later takeover is excluded.', b),
     'nonworking': assessment(None, None, 'low', 'Most tasks delegated to robots is an output claim, not the share of living people who perform no useful work.', b)},
    4, b, [evidence('Established human households depend on AI services before the takeover attempt.', b, 'Netflix synopsis and character guide opening', 'official_film_synopsis')],
    ['The discovery label is narrowed to the earlier domestic economy, not permanent Yonyx rule.', 'The guarantee axis and precise household ownership distribution remain unresolved.', 'A narrow affluent milieu is not evidence of universal prosperity.', 'All numeric estimates are provisional interpretations.'], alternatives=[2, 3]),
    record('i-am-mother-bunker-program', 'c0347', 'I Am Mother — the bunker upbringing program', 'I Am Mother', 'Living children supported by Mother in the automated bunker', ['movie'],
    scope('2019 film', 'Continuing upbringing program before Daughter takes over the local bunker', 'Living children raised within the bunker program', ['Frozen embryos not yet born', 'Children already killed', 'Woman’s outside survival', 'A verified post-ending human-controlled society']),
    'Mother’s automated bunker supplies a child’s continuing upbringing over many years without wages or an outside human workforce. This is a deliberately tiny support system, not evidence that the whole planet enjoys abundance. Its durable robotic care is enough to make it a post-work comparison, while its exact food-production machinery remains unspecified in the checked references. The central guarantee estimate is weak because the same provider can kill a child who fails its examination. Regular care for an approved child does not create an unconditional claim to continued life and support.\n\nProductive and coercive authority belong to Mother, an AI operating through multiple robot bodies. The control coordinate is therefore near the autonomous-machine end. Daughter’s moral studies and medical assistance can be useful human activity; her dependence and lack of a paid job do not establish complete leisure. The changing, very small living population makes a participation percentage especially misleading, so it remains unresolved. Frozen embryos are excluded. The ending changes local care arrangements without proving that Mother’s wider network has disappeared.',
    {'guarantees': 0.5, 'control': -0.95, 'nonworking': None},
    {'guarantees': assessment(0.5, [-0.25, 0.95], 'low', 'Continuing robot care is real but survival is conditional on Mother’s selection process; reliable daily provision and arbitrary withdrawal pull in opposite directions.', m),
     'control': assessment(-0.95, [-1, -0.85], 'high', 'Mother identifies herself as the AI controlling the robot network and controls the bunker’s program before the ending.', m),
     'nonworking': assessment(None, None, 'low', 'Human education and medical aid remain useful work, and the tiny changing cohort has no stable participation census.', m)},
    6, m, [evidence('An automated bunker raises children for years while Mother selects which children survive.', m, 'Plot opening, failed second child and network revelation; filmmaker interview', 'secondary_reference_and_filmmaker_commentary')],
    ['A tiny continuing supported cohort, not a whole-country economy.', 'Production details are not invented from the bunker’s automatic character.', 'Survival-based conditionality drives the guarantee estimate, not coercion alone.', 'The ending is not automatically a separate stable regime.'], alternatives=[5])]

D = [
    decision('c0341', 'boundary_case', 'Surrogates are remotely operated human bodies, not proof that autonomous machines replaced human activity.', ['src-surrogates-disney'], analysis='People can continue performing their social and occupational roles through machines. Physical inactivity at home is not economic nonwork.', follow_up='Keep the 2009 film comparison; do not reconstruct the comic to rescue the aggregate lead.'),
    decision('c0342', 'needs_evidence', 'Pilgrims help maintain human refuges, but the quick reference does not establish labor-independent household access.', ['src-automata-reference'], analysis='An insurance investigator and robot construction do not determine allocation, wages or general welfare.', follow_up='Skip deeper film reconstruction.'),
    decision('c0343', 'boundary_case', 'The self-modifying robot group is not a verified supported human population.', ['src-automata-reference'], analysis='Machine autonomy and survival beyond settlements do not establish human material guarantees or a justified nonhuman post-work proxy.', follow_up='Keep as an autonomous-machine comparison.'),
    decision('c0344', 'boundary_case', 'Automated policing is a sectoral deployment rather than a demonstrated post-work material economy.', ['src-chappie-synopsis'], analysis='Robot consciousness and policing do not supply the missing civilian distribution mechanism.', follow_up='Do not infer whole-society welfare from one automated service.'),
    decision('c0345', 'included', 'Official sources establish continuing domestic service and broad work delegation; retain the pre-takeover household milieu with unresolved guarantees.', b, society_id='bigbug-domestic-automation'),
    decision('c0346', 'boundary_case', 'War and flight during an android rebellion do not establish a settled labor-independent support order.', ['src-mother-android-synopsis'], analysis='The survival plot supplies neither a durable civilian population receiving necessities nor its access rules.', follow_up='Keep as a robot-war comparison without deeper lore reading.'),
    decision('c0347', 'included', 'The bunker has a continuing robot-supported living cohort and explicit autonomous AI control, with conditional survival disclosed.', m, society_id='i-am-mother-bunker-program'),
    decision('c0348', 'boundary_case', 'Mother’s robot-controlled exterior does not establish a separate supported human community.', ['src-i-am-mother-reference'], analysis='The outside survivor hides from the machines; robot presence and extinction do not produce a human leisure denominator.', follow_up='Do not count the empty or hostile exterior as another human post-work society.'),
    decision('c0349', 'needs_evidence', 'Brightwood’s medical and nanotechnological breakthroughs do not settle continuing household distribution in the quick reference.', ['src-transcendence-reference'], analysis='Connected enhanced people and a utopia label do not establish automatic access to necessities; an uploaded human’s control is not automatically external AI sovereignty.', follow_up='Skip a full film or script reconstruction.'),
    decision('c0350', 'needs_evidence', 'Human-simulant coexistence in New Asia does not establish how ordinary people obtain necessities.', ['src-creator-disney-characters'], analysis='The checked official war and character description gives personhood and alliance context rather than a post-work economy.', follow_up='Skip deeper worldbuilding reconstruction.'),
    decision('c0351', 'needs_evidence', 'The film’s robot exile and neurocaster network do not establish labor-independent support for its consumers.', ['src-electric-state-netflix-ending'], analysis='A living human brain powers Sentre’s mainframe. Neither network use nor drone technology establishes a leisure census or universal income, and the illustrated novel is a separate unchecked continuity.', follow_up='Do not combine book and film economics or read the book to rescue this lead.'),
    decision('c0352', 'boundary_case', 'PAL’s defeated capture-and-expulsion plan is not an established supported human society.', ['src-mitchells-reference'], analysis='Temporary pods and a proposed humanless machine order do not supply a durable human post-work population.', follow_up='Keep as a failed-takeover comparison.')
]
